using AcxiomCRM.Data;using AcxiomCRM.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace AcxiomCRM.Controllers;
[ApiController][Authorize][Route("api")]public class ApiController(AppDbContext db,UserManager<AppUser> users):ControllerBase{
[HttpGet("customers")]public async Task<IActionResult> Customers(){var uid=users.GetUserId(User);var all=User.IsInRole("Admin");var manager=User.IsInRole("Manager");var team=users.Users.Where(u=>u.ManagerId==uid).Select(u=>u.Id);return Ok(await db.Customers.Where(x=>all||x.OwnerId==uid||(manager&&team.Contains(x.OwnerId))).Select(x=>new {x.Id,x.Name,x.Email,x.Phone,x.CompanyName,x.Status}).ToListAsync());}
[HttpGet("customers/{id:int}")]public async Task<IActionResult> Customer(int id){var uid=users.GetUserId(User);var x=await db.Customers.Where(x=>x.Id==id&&(User.IsInRole("Admin")||x.OwnerId==uid||(User.IsInRole("Manager")&&users.Users.Any(u=>u.Id==x.OwnerId&&u.ManagerId==uid)))).Select(x=>new {x.Id,x.Name,x.Email,x.Phone,x.CompanyName,x.Status}).FirstOrDefaultAsync();return x==null?NotFound():Ok(x);}
[HttpGet("leads")]public async Task<IActionResult> Leads(){var uid=users.GetUserId(User);return Ok(await db.Leads.Where(x=>User.IsInRole("Admin")||x.OwnerId==uid||(User.IsInRole("Manager")&&users.Users.Any(u=>u.Id==x.OwnerId&&u.ManagerId==uid))).Select(x=>new{x.Id,x.Name,x.Status,x.Source}).ToListAsync());}
[HttpGet("opportunities")]public async Task<IActionResult> Opportunities(){var uid=users.GetUserId(User);return Ok(await db.Opportunities.Where(x=>User.IsInRole("Admin")||x.OwnerId==uid||(User.IsInRole("Manager")&&users.Users.Any(u=>u.Id==x.OwnerId&&u.ManagerId==uid))).Select(x=>new{x.Id,x.Name,x.Stage,x.Amount,x.Probability}).ToListAsync());}}
